mapper.select:
SELECT * FROM 0721acgn.tb_animation


        AND (
            `genre` = #{genre}
            OR LOCATE(#{genre}, IFNULL(`genre`, '')) > 0
        )


        AND status = #{status}


        AND LENGTH(TRIM(IFNULL(releasedate,''))) >= 4
        AND CAST(LEFT(TRIM(releasedate), 4) AS UNSIGNED) >= #{yearMin}


        AND LENGTH(TRIM(IFNULL(releasedate,''))) >= 4
        AND CAST(LEFT(TRIM(releasedate), 4) AS UNSIGNED) <= #{yearMax}




        ORDER BY rating DESC, id DESC


        ORDER BY updated_at DESC, id DESC


        ORDER BY id DESC


LIMIT #{offset}, 20

SELECT * FROM 0721acgn.tb_animation WHERE TRIM(IFNULL(name, '')) = TRIM(#{name})
AND id != #{excludeId}
ORDER BY id DESC LIMIT 30

SELECT * FROM 0721acgn.tb_animation WHERE CHAR_LENGTH(#{seriesPrefix}) >= 3
AND id != #{excludeId}
AND TRIM(IFNULL(name, '')) LIKE CONCAT(#{seriesPrefixEsc}, '%') ESCAPE '!' ORDER BY id DESC LIMIT 200
